<?php
use PHPUnit\Framework\TestCase;use ZinCelestial\Platform\Workflow\Durable\WorkflowRunRepository;
final class PersistenceMultisiteIntegrationTest extends TestCase {public function test_all_queries_bind_tenant_and_lease_token():void{$db=new class extends wpdb{public array $sql=[];public function __construct(){}public function prepare($q,...$a){$this->sql[]=[$q,$a];return $q;}public function query($q){return 1;}public function get_row($q,$o=OBJECT,$y=0){return null;}};$r=new WorkflowRunRepository($db,'wp_zcp_workflow_runs',42);$this->assertTrue($r->claim('run-a','worker-a',30));$this->assertTrue($r->heartbeat('run-a','worker-a',30));$r->release('run-a','worker-a');foreach($db->sql as [$sql,$args])$this->assertStringContainsString('site_id=%d',$sql);$this->assertStringContainsString('lease_token=%s',$db->sql[1][0]);}public function test_invalid_tenant_rejected():void{$this->expectException(RuntimeException::class);new WorkflowRunRepository($this->createMock(wpdb::class),'table',0);}}
